```typescript
// Checkout.test.tsx
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { vi, describe, it, expect, beforeEach } from 'vitest';
import { Checkout } from './Checkout';
import { CartProvider } from './CartContext';
import { PaymentProvider } from './PaymentContext';

const mockProcessPayment = vi.fn();
const mockClearCart = vi.fn();

const mockCartItems = [
  { id: '1', name: 'Pointed Hat', price: 29.99 },
  { id: '2', name: 'Broomstick', price: 149.99 }
];

const renderCheckout = (cartItems = mockCartItems) => {
  return render(
    <CartProvider value={{ items: cartItems, total: 179.98, clearCart: mockClearCart }}>
      <PaymentProvider value={{ processPayment: mockProcessPayment }}>
        <Checkout onComplete={vi.fn()} onCancel={vi.fn()} />
      </PaymentProvider>
    </CartProvider>
  );
};

describe('Checkout - Happy Path', () => {
  it('completes full checkout flow when everything is proper', async () => {
    const user = userEvent.setup();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-123' });
    renderCheckout();

    // Shipping
    await user.type(screen.getByLabelText(/street address/i), '123 Lancre Lane');
    await user.type(screen.getByLabelText(/city/i), 'Lancre');
    await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
    await user.type(screen.getByLabelText(/zip code/i), '90210');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    // Payment
    await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
    await user.type(screen.getByLabelText(/expiry/i), '12/25');
    await user.type(screen.getByLabelText(/cvv/i), '123');
    await user.type(screen.getByLabelText(/name on card/i), 'Esmerelda Weatherwax');
    await user.click(screen.getByRole('button', { name: /review order/i }));

    // Review & Submit
    expect(screen.getByText(/pointed hat/i)).toBeInTheDocument();
    await user.click(screen.getByRole('button', { name: /place order/i }));

    await waitFor(() => {
      expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
    });
  });
});

describe('Checkout - Validation', () => {
  it('shows errors for empty shipping fields - I aten\'t having with laziness', async () => {
    const user = userEvent.setup();
    renderCheckout();

    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    expect(screen.getByText(/street address is required/i)).toBeInTheDocument();
    expect(screen.getByText(/city is required/i)).toBeInTheDocument();
  });

  it('validates ZIP code format properly', async () => {
    const user = userEvent.setup();
    renderCheckout();

    await user.type(screen.getByLabelText(/zip code/i), 'notazip');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
  });
});

describe('Checkout - Edge Cases', () => {
  it('handles empty cart by showing proper message', () => {
    renderCheckout([]);
    expect(screen.getByText(/your cart is empty/i)).toBeInTheDocument();
  });

  it('shows error when payment fails and allows retry', async () => {
    const user = userEvent.setup();
    mockProcessPayment.mockRejectedValueOnce(new Error('Card declined'));
    // ... complete to review step, then:

    await user.click(screen.getByRole('button', { name: /place order/i }));

    await waitFor(() => {
      expect(screen.getByRole('alert')).toHaveTextContent(/card declined/i);
    });
    expect(screen.getByRole('button', { name: /place order/i })).toBeEnabled();
  });
});

describe('Checkout - Accessibility', () => {
  it('marks invalid fields with aria-invalid', async () => {
    const user = userEvent.setup();
    renderCheckout();

    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    expect(screen.getByLabelText(/street address/i)).toHaveAttribute('aria-invalid', 'true');
  });
});
